package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.PreparacionCierreCajaDto;
import com.citacloud.springboot.contacloud.app.models.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CierreCajaServiceTest {
 @Test void calculaSoloEfectivoYClasificaEntradasYSalidas(){UUID t=UUID.randomUUID(),e=UUID.randomUUID(),c=UUID.randomUUID(),m=UUID.randomUUID(),s=UUID.randomUUID(),u=UUID.randomUUID();MovimientoFinanciero venta=MovimientoFinanciero.ventaContado(t,e,LocalDate.now(),c,m,new BigDecimal("100"),"F1",UUID.randomUUID(),s,u);MovimientoFinanciero cobro=MovimientoFinanciero.cobroVenta(t,e,LocalDate.now(),TipoCuentaDinero.CASH_REGISTER,c,m,new BigDecimal("50"),"F2",UUID.randomUUID(),MedioPagoMovimiento.CASH,s,null,u);MovimientoFinanciero tarjeta=MovimientoFinanciero.cobroVenta(t,e,LocalDate.now(),TipoCuentaDinero.BANK_ACCOUNT,UUID.randomUUID(),m,new BigDecimal("80"),"F3",UUID.randomUUID(),MedioPagoMovimiento.CARD,null,null,u);MovimientoFinanciero vale=MovimientoFinanciero.valeCaja(t,e,LocalDate.now(),c,m,new BigDecimal("10"),"M1","V1","Vale","A",null,UUID.randomUUID(),s,u);MovimientoFinanciero otro=MovimientoFinanciero.manualCaja(t,e,TipoMovimientoFinanciero.EXPENSE,LocalDate.now(),c,m,new BigDecimal("5"),"M2",UUID.randomUUID(),"Salida",null,null,s,u);var r=CierreCajaService.resumen(List.of(venta,cobro,tarjeta,vale,otro));assertEquals(0,new BigDecimal("100").compareTo(r.ventas()));assertEquals(0,new BigDecimal("50").compareTo(r.cobros()));assertEquals(0,new BigDecimal("150").compareTo(r.totalEntradas()));assertEquals(0,new BigDecimal("10").compareTo(r.vales()));assertEquals(0,new BigDecimal("15").compareTo(r.totalSalidas()));}
 @Test void preparacionEsCiega(){Set<String> nombres=new HashSet<>();Arrays.stream(PreparacionCierreCajaDto.class.getRecordComponents()).forEach(x->nombres.add(x.getName().toLowerCase(Locale.ROOT)));assertFalse(nombres.contains("esperado"));assertFalse(nombres.contains("contado"));assertFalse(nombres.contains("diferencia"));assertFalse(nombres.contains("movimientos"));}
}
